input.sparql:
SELECT DISTINCT ?zone ?zoneName ?tsid WHERE {
  ?point a brick:Zone_Air_Temperature_Sensor .
  ?point brick:hasParent? ?zone .
  ?zone rdfs:label ?zoneName .
  ?point ref:hasTimeseriesId ?tsid .
}

SELECT DISTINCT ?point ?zone WHERE {
  ?point a brick:Zone_Air_Temperature_Sensor .
  ?point brick:hasParent ?zone .
}

SELECT ?sensor ?zone ?label ?tsref WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  ?sensor brick:isPointOf ?zone .
  ?zone rdfs:label ?label .
  OPTIONAL { ?sensor ref:hasExternalReference ?e . ?e ref:hasTimeseriesId ?tsref }
}
